# Test m=5
m = 5
S = list(range(1, m + 1))
T = m * (m + 1) // 6
print(f"m={m}, T={T}")

# Check if X={5} works, as found in manual check
X = {5}
S_X = sum(X)

if S_X == T:
    S_prime = [x for x in S if x not in X]
    print(f"S'={S_prime}")

    # Check for Y subset of S' summing to T=5
    from itertools import combinations
    found_Y = False
    for k in range(1, len(S_prime) + 1):
        for subset in combinations(S_prime, k):
            if sum(subset) == T:
                print(f"Found Y: {set(subset)}")
                found_Y = True
                break
        if found_Y:
            break

    if found_Y:
        print("m=5 yields a solution.")
    else:
        print("m=5 does not yield a solution.")
else:
    print("m=5 does not yield a solution based on X={5}.")
